rowdata.pyStepsJavaSource:
String pageName = tools.getParameterPage().getString("pyPageName");
ClipboardPage pyReportContentPage = tools.findPage(pageName, true);
if(pyReportContentPage!=null) {
    pyReportContentPage.clearMessages(); 		
}
reportPageExists = false;
//BUG-326790
//Removing timestamp in generation of temp page name
com.pega.pegarules.pub.util.Random mRandom = com.pega.pegarules.pub.context.ThreadContainer.get().getSystemRandom();
tempPageName ="TempReportPage_"+mRandom.getRandomHex(10);
String reportPageName = tools.getParameterPage().getString("pyReportPageName");
if(reportPageName != null) {
// check if the page exists
ClipboardPage reportPage = tools.findPage(reportPageName, true);
if(reportPage != null) 
	reportPageExists = true;
}
if(reportPageExists)
    tools.getParameterPage().putString("pyRunType", "FullResolve");
String reportParamPage = tools.getParameterPage().getString("pyReportParamPageName");

if(!StringUtils.isBlank(reportParamPage)) {
    // check if the page exists
    reportParamPageExists = false;
    ClipboardPage reportPage = tools.findPage(reportParamPage, true);
    if(reportPage != null) {
        reportParamPageExists = true;
        if(reportPage.getIfPresent(".pyPagingSettings") != null) {
	        hasPagingSetttings = true;
        }
    }
}

tools.getParameterPage().putString("pyRunType", "FullResolve");

String strViewClass = tools.findPage("pegaInternalReportTempPage").getString(".pyClassName");
String strViewClassParam = tools.getParamValue("pyReportClass");

ClassDefinition cd = tools.getDatabase().getClassDef(strViewClass);
ClassDefinition cdParam = tools.getDatabase().getClassDef(strViewClassParam);

if (cd != null)
{
	if (!cd.isConcrete())
		{
                     if(cdParam != null && cdParam.isConcrete()){
                         tools.findPage("pegaInternalReportTempPage").putString("pyClassName",strViewClassParam);
                         //required for the case when we are not using copyProperties for new report.
                         myStepPage.putString("pyClassName", strViewClassParam);
                        }
		}
}

//IN ORDER TO SUPPORT FUNCTIONALITY TO ADD OR REMOVE LIST OR AGGREGATE AND GROUPBY FIELDS AS A PART OF US-27031
ClipboardProperty listFields = myStepPage.getIfPresent("pyListFields");//populating list fields from activity
ClipboardProperty aggregateFields = myStepPage.getIfPresent("pyAggregate");//populating the aggregate properties from activity
ClipboardProperty groupByFields = myStepPage.getIfPresent("pyGroupBy");//populating the group by properties from activity
isAggregate = tools.findPage("pegaInternalReportTempPage").getPage("pyContent").getProperty("pxIsSummary").getStringValue();
if(listFields != null && aggregateFields != null){
	//myStepPage.addMessage("Cannot set both the aggregate as well as list fields");
         listAggFieldsSet = "true";
}
else if(aggregateFields == null && groupByFields != null){
	areOnlyGroupbySet = true;
}
else{
	listAggFieldsSet = "false";
	areOnlyGroupbySet = false;
	if(listFields != null || aggregateFields != null){//Check to see if any list fields are being added from the activity
		//tools.getParameterPage().putString("pyRunType", "FullResolve");
		ClipboardProperty columnsInfoLF = tools.findPage("pegaInternalReportTempPage").getPage("pyContent").getPage("pyFields").getProperty("pyListFields");//populating list fields from RD
		ClipboardProperty aggregatesInfo = tools.findPage("pegaInternalReportTempPage").getPage("pyContent").getPage("pyFields").getProperty("pyAggregate");//populating aggregate fields from the RD page
		ClipboardProperty groupByInfo = tools.findPage("pegaInternalReportTempPage").getPage("pyContent").getPage("pyFields").getProperty("pyGroupBy");//populating group by fields from the RD page
		ClipboardProperty columnsInfoUI = tools.findPage("pegaInternalReportTempPage").getPage("pyUI").getPage("pyBody").getProperty("pyUIFields");//This is to display the properties on the report viewer

		if(columnsInfoLF != null){
			for(int j=columnsInfoLF.size(); j>=1; j--){//remove the list fields from RD page
				columnsInfoLF.remove(j);
			}
		}
		if(aggregatesInfo != null){
			for(int i = aggregatesInfo.size(); i >= 1; i--){//remove the existing aggregate fields
			aggregatesInfo.remove(i);
			}
		}
		if(groupByInfo != null){
			for(int j = groupByInfo.size(); j >= 1; j--){//remove existing groupby fields
				groupByInfo.remove(j);
			}
		}	

		for(int j=columnsInfoUI.size(); j>=1; j--){//remove UIFields
				columnsInfoUI.remove(j);
		}

		if(listFields != null){
			for(int i=1; i<= listFields.size(); i++){//Iterating through the list fields of the activity and placing them in the RD page

				ClipboardPage listPage = listFields.getPageValue(i);
				String fieldName = listPage.getProperty("pyFieldName").getStringValue();
				String dataType = listPage.getProperty("pyDataType").getStringValue();
				String columnHide = listPage.getProperty("pyIsColumnHide").getStringValue();
				String columnWidth = listPage.getProperty("pyColumnWidth").getStringValue();
				String columnWidthUnit = listPage.getProperty("pyColumnWidthUnit").getStringValue();
				String sortOrder = listPage.getProperty("pySortOrder").getStringValue();
				String sortType = listPage.getProperty("pySortType").getStringValue();
				String fieldLabel = listPage.getProperty("pyFieldLabel").getStringValue();
                String pyColumnFilteringDropDown = listPage.getString(".pyColumnFilteringDropDown");
                String pzPropertyType  = listPage.getString(".pzPropertyType");

				ClipboardProperty fieldFormat = listPage.getProperty(".pyFieldFormat");
				ClipboardPage mainPage = columnsInfoLF.getPageValue(ClipboardProperty.LIST_APPEND);//Populating in the main RD page
				mainPage.putString("pyFieldName", fieldName);
				mainPage.putString("pyFieldLabel", fieldLabel);
				mainPage.putString("pySortOrder", sortOrder);
				mainPage.putString("pySortType", sortType);	

				ClipboardPage mainPageUI = columnsInfoUI.getPageValue(ClipboardProperty.LIST_APPEND);//Populating in the UI page
				mainPageUI.putString("pyFieldName", fieldName);
				mainPageUI.putString("pySortOrder", sortOrder);
				mainPageUI.putString("pySortType", sortType);			
				mainPageUI.putString("pyFieldLabel", fieldLabel);
				mainPageUI.putString("pyDataType", dataType);
				mainPageUI.putString("pyHide", columnHide);
				mainPageUI.putString("pyFieldWidth", columnWidth);
				mainPageUI.putString("pyFieldWidthUnit", columnWidthUnit);
				mainPageUI.put(".pyFieldFormat",fieldFormat);
                mainPageUI.putString(".pyColumnFilteringDropDown",pyColumnFilteringDropDown);
                mainPageUI.putString(".pzPropertyType",pzPropertyType);
			}
		}
		else if(aggregateFields != null){
			for(int i = 1 ; i <= aggregateFields.size(); i++){//replacing the aggregate fields
				ClipboardPage aggregatesPage = aggregateFields.getPageValue(i);
				String aggFunction = aggregatesPage.getProperty("pyAggregateFunction").getStringValue();
				String dataType = aggregatesPage.getProperty("pyDataType").getStringValue();
				String columnHide = aggregatesPage.getProperty("pyIsColumnHide").getStringValue();
				String columnWidth = aggregatesPage.getProperty("pyColumnWidth").getStringValue();
				String columnWidthUnit = aggregatesPage.getProperty("pyColumnWidthUnit").getStringValue();

				ClipboardPage pyAggregateField = aggregatesPage.getPage("pyAggregateField");

				String aggFieldName = pyAggregateField.getProperty("pyFieldName").getStringValue();
				String aggFieldLabel = pyAggregateField.getProperty("pyFieldLabel").getStringValue();
				String aggFieldSortOrder = pyAggregateField.getProperty("pySortOrder").getStringValue();
				String aggFieldSortType = pyAggregateField.getProperty("pySortType").getStringValue();

				ClipboardPage mainAggPage = aggregatesInfo.getPageValue(ClipboardProperty.LIST_APPEND);

				mainAggPage.putString("pyAggregateFunction", aggFunction);
				mainAggPage.putPage("pyAggregateField", pyAggregateField);

				ClipboardPage UIPageAgg = columnsInfoUI.getPageValue(ClipboardProperty.LIST_APPEND);

				UIPageAgg.putString("pyFieldName", aggFieldName);
				UIPageAgg.putString("pyFieldLabel", aggFieldLabel);
				UIPageAgg.putString("pySortOrder", aggFieldSortOrder);
				UIPageAgg.putString("pySortType", aggFieldSortType);
				UIPageAgg.putString("pyFunction", aggFunction);
				UIPageAgg.putString("pyDataType", dataType);
				UIPageAgg.putString("pyHide", columnHide);
				UIPageAgg.putString("pyFieldWidth", columnWidth);
				UIPageAgg.putString("pyFieldWidthUnit", columnWidthUnit);
				isAggregate = "true";
			}

			if(groupByFields != null){
				for(int j = 1; j <= groupByFields.size(); j++){//replacing the group by fields
					ClipboardPage groupByPage = groupByFields.getPageValue(j);
					String dataType = groupByPage.getProperty("pyDataType").getStringValue();
					String columnHide = groupByPage.getProperty("pyIsColumnHide").getStringValue();
					String columnWidth = groupByPage.getProperty("pyColumnWidth").getStringValue();
					String columnWidthUnit = groupByPage.getProperty("pyColumnWidthUnit").getStringValue();

					ClipboardPage pyGroupByField = groupByPage.getPage("pyGroupByField");

					String grpByFieldName = pyGroupByField.getProperty("pyFieldName").getStringValue();
					String grpByFieldLabel = pyGroupByField.getProperty("pyFieldLabel").getStringValue();
					String grpByFieldSortOrder = pyGroupByField.getProperty("pySortOrder").getStringValue();
					String grpByFieldSortType = pyGroupByField.getProperty("pySortType").getStringValue();
					String pyColumnFilteringDropDown = pyGroupByField.getString(".pyColumnFilteringDropDown");
                    String pzPropertyType  = pyGroupByField.getString(".pzPropertyType");

					ClipboardPage mainGrpByPage = groupByInfo.getPageValue(ClipboardProperty.LIST_APPEND);
					mainGrpByPage.putPage("pyGroupByField", pyGroupByField);
					ClipboardPage UIPageGrpBy = columnsInfoUI.getPageValue(ClipboardProperty.LIST_APPEND);

					UIPageGrpBy.putString("pyFieldName", grpByFieldName);
					UIPageGrpBy.putString("pyFieldLabel", grpByFieldLabel);
					UIPageGrpBy.putString("pySortOrder", grpByFieldSortOrder);
					UIPageGrpBy.putString("pySortType", grpByFieldSortType);
					UIPageGrpBy.putString("pyDataType", dataType);
					UIPageGrpBy.putString("pyHide", columnHide);
					UIPageGrpBy.putString("pyFieldWidth", columnWidth);
					UIPageGrpBy.putString("pyFieldWidthUnit", columnWidthUnit);
                    UIPageGrpBy.putString(".pyColumnFilteringDropDown",pyColumnFilteringDropDown);
                    UIPageGrpBy.putString(".pzPropertyType",pzPropertyType);
				}
			}
		}
	}
}

ClipboardPage tempReportPage = tools.findPage("pegaInternalReportTempPage");
String pyUnionNotApplied = tempReportPage.getString(".pyContent.pyUnionNotApplied");
if(null != pyUnionNotApplied && !"true".equalsIgnoreCase(pyUnionNotApplied)){
  tempReportPage.putString(".pyContent.pyUnionNotApplied", myStepPage.getString(".pyUnionNotApplied"));
}

//COMMENTED IN ORDER TO SUPPORT FUNCTIONALITY TO ADD OR REMOVE COLUMNS FOR US-27031
