ClipboardProperty cpFilterSettings = myStepPage.getIfPresent("pyFilterSettings"); // Param Source

if (cpFilterSettings != null)
{
ClipboardProperty pFilterLogic = cpFilterSettings.getProperty(".pyFilterLogic");
String logicFromAPI = pFilterLogic.getStringValue();
if (!StringUtils.isBlank(logicFromAPI)){
//Format the filterLogic to have 1 space for each token
        logicFromAPI = logicFromAPI .replaceAll("\\s+"," ");
        logicFromAPI  = logicFromAPI .replaceAll("[(]"," "+"("+" ");
		logicFromAPI = logicFromAPI .replaceAll("[)]"," "+")"+" ");
		logicFromAPI = logicFromAPI .replaceAll("\\s+"," ");
                logicFromAPI = logicFromAPI.replaceAll("\\b[Aa][nN][dD]\\b", "AND").replaceAll("\\b[oO][rR]\\b", "OR");
		pFilterLogic.setValue(logicFromAPI); 

ClipboardProperty cpFilter = cpFilterSettings.getProperty("pyFilter");
java.util.Iterator itr = cpFilter.iterator();
java.util.ArrayList arrBlankLabels = new java.util.ArrayList();
java.util.ArrayList arrFilterLabels = new java.util.ArrayList();
java.util.HashMap hmLabelsNoCase = new java.util.HashMap();
while (itr.hasNext()) {

ClipboardProperty itrFilter = (ClipboardProperty) itr.next();

ClipboardPage pgFilter = itrFilter.getPageValue();
if(pgFilter.getString(".pyLogicLabel").equals("")){
	arrBlankLabels.add(itrFilter.getReference());
}
else{
	arrFilterLabels.add(pgFilter.getString(".pyLogicLabel"));  
	hmLabelsNoCase.put(pgFilter.getString(".pyLogicLabel").toLowerCase(),pgFilter.getString(".pyLogicLabel"));
}
}

int num=65;
int counter = 1;
String str="";
boolean bFound = false;
while(!arrBlankLabels.isEmpty()) {		
if(num > 90){
	str = "A" + counter++;	
}
else{
	char c = (char)num++;
	str = "" + c;
}

if(!hmLabelsNoCase.containsKey(str.toLowerCase())) {
	String strPropRef = (String)arrBlankLabels.get(0);
	arrBlankLabels.remove(0);
	tools.getProperty(strPropRef).getProperty(".pyLogicLabel").setValue(str);
	String strFilterLogic = pFilterLogic.getStringValue();

             if(strFilterLogic.equals("")){
		pFilterLogic.setValue(str);
	}
	else{				
		String logic = " " + strFilterLogic + " ";
		String strTemp1 = " " + str + " ";
		String strTemp2 = "( " + str + " ";
		String strTemp3 = " " + str + " )";
		if((logic.indexOf(strTemp1) == -1) && (logic.indexOf(strTemp2) == -1) && (logic.indexOf(strTemp3) == -1)){
			pFilterLogic.setValue(strFilterLogic + " AND " + str);					
		}
	}
	arrFilterLabels.add(str);
	hmLabelsNoCase.put(str.toLowerCase(),str);
}
}
String strFilterLogic = pFilterLogic.getStringValue().trim();

java.util.ArrayList labelsInLogic = new java.util.ArrayList();
java.util.StringTokenizer stk = new java.util.StringTokenizer(strFilterLogic , " )(" , false);
while (stk.hasMoreTokens())
{
String strToken = stk.nextToken();
if (!strToken.equalsIgnoreCase("AND") && !strToken.equalsIgnoreCase("OR") && !strToken.equalsIgnoreCase("NOT")) {
	if(!labelsInLogic.contains(strToken)) {
		labelsInLogic.add(strToken);
    }
 }
}

/*  Remove all junk labels which are not present in filter labels from the Filter logic.*/  
for (int i=0 ; i< labelsInLogic.size() ; i++){	
str = (String)labelsInLogic.get(i);

strFilterLogic = strFilterLogic.replaceAll("\\s+"," "); 

if(!arrFilterLabels.contains(str)){

	strFilterLogic = pega_rulesengine_reportingutils.pzRemoveTokenFromExpression(strFilterLogic, str);

	strFilterLogic = strFilterLogic.replaceAll("-", "");
}
}

/*  Append missing filter labels to the Filter logic. */
for (int i=0 , nArrLabelsSize = arrFilterLabels.size() ; i< nArrLabelsSize ; i++){	
String missingLabel = (String)arrFilterLabels.get(i);
if(!labelsInLogic.contains(missingLabel)){
	if (strFilterLogic.trim().equals(""))				
		strFilterLogic = missingLabel;				
	else
		strFilterLogic = strFilterLogic + " AND " + missingLabel;
}
}


String strTest = strFilterLogic;	
int k = 0;	
int ascii = 0;
pFilterLogic.setValue(strFilterLogic.trim());
pFilterLogic.hasInvalidValue();
}
}

ClipboardProperty cpFilterSettings = myStepPage.getIfPresent("pyFilterSettings"); // Param Source

if (cpFilterSettings != null)
{
ClipboardProperty pyCompositeFilter1 = cpFilterSettings.getProperty(".pyCompositeFilter");
pyCompositeFilter = pyCompositeFilter1.getStringValue();
}

Map filteringParamsMap = new java.util.HashMap();

ClipboardProperty cpFilterSettings = myStepPage.getIfPresent("pyFilterSettings"); // Param Source
ClipboardProperty cpFilter = null;


if (cpFilterSettings != null) {
	ClipboardPage tempReportPage = tools.findPage("pegaInternalReportTempPage");

	//Added to for RD FUA cache story to fully resolve if there is any change in the filters.
	tools.getParameterPage().putString("pyRunType", "FullResolve");

	ClipboardPage tempReportContentPage = tempReportPage.getProperty("pyContent").getPageValue();
	String pyGetDistinctRows = cpFilterSettings.getStringValue("pyGetDistinctRows");
	String pyFilterLogicLabelPrefix = cpFilterSettings.getStringValue("pyFilterLogicLabelPrefix");
	String  pyChangeFilterLogic = cpFilterSettings.getStringValue("pyChangeFilterLogic");
	ClipboardProperty tempFilters = tempReportPage.getProperty(".pyUI.pyBody.pyUIFilters"); // Target RD Page
	boolean isCascadingFilters = cpFilterSettings.getPageValue().getBoolean("pyCascadingFilters");
	if ((pyGetDistinctRows).equals("true")) {
		tempFilters.getPageValue().putString("pyGetDistinctRows", pyGetDistinctRows);
	}
	if(!pyGetDistinctRows.equals("true") || isCascadingFilters){

		cpFilter = cpFilterSettings.getPageValue().getIfPresent("pyFilter"); // Param Source

		ClipboardPage pgTempFilters = tempFilters.getPageValue();
		String  pyExtraBracesAddedInFilterLogic = pgTempFilters.getString("pyExtraBracesAddedInFilterLogic");	
		ClipboardProperty cpTempFilteR = pgTempFilters.getProperty("pyFilter");
		String prevFilterName = "";
		String filterLogicfromRule = "";
		String filterLogicfromAPI = cpFilterSettings.getStringValue("pyFilterLogic");
		Boolean isFilterLogicBlank = StringUtils.isBlank(filterLogicfromAPI);

		//Replace the Existing filters if ReplaceFilters is set to true
		String pyReplaceFilters = cpFilterSettings.getStringValue("pyReplaceFilters");
		if (pyReplaceFilters.equalsIgnoreCase("true")) {
			filterLogicfromRule = "";
			while (cpTempFilteR.size() > 0) {
				cpTempFilteR.remove(cpTempFilteR.size());
			}
		} else {
			filterLogicfromRule = pgTempFilters.getString("pyFilterLogic");
			if (!StringUtils.isBlank(filterLogicfromRule)) {
				if (!"true".equals(pyExtraBracesAddedInFilterLogic)) {
					filterLogicfromRule = " (  " + filterLogicfromRule + " ) ";
					pgTempFilters.putString("pyExtraBracesAddedInFilterLogic","true");
				}
			}
			if (cpTempFilteR.size() == 1) {
				String strFilterName = cpTempFilteR.getPageValue(1).getString("pyFilterName");

				if (strFilterName.equals("")) {
					filterLogicfromRule = "";

					cpTempFilteR.remove(1);
				}
			}
			if (!StringUtils.isBlank(filterLogicfromRule) && cpFilter.size() > 0) {
				filterLogicfromRule += " AND ";
			}
		}

		for (int i = 1; i <= cpFilter.size(); i++) {

			ClipboardPage filter = cpFilter.getPageValue(i);
			/* determine data type of the column and read the appropriate ValueList */
			String valueLists[] = {
					"pyDateTimeFilterValue", "pyDateFilterValue", "pyDecimalFilterValue", "pyIntegerFilterValue", "pyDoubleFilterValue", "pyTextFilterValue"
			};

			ClipboardProperty cpValueList = null;
			for (int j = 0; j < valueLists.length; j++) {
				cpValueList = filter.getIfPresent(valueLists[j]);
				if (cpValueList != null) {
					break;
				}
			}

			boolean doOring = false;
			String pyFilterLogic = "";
			pyFilterLogic += "(";
			String filterName = filter.getString("pyFilterName");

			String filterOperation = filter.getString("pyFilterOperation");
			String useNullIfEmpty = filter.getString("pyUseNullIfEmpty");
			String oldFilterLabel = filter.getString("pyLogicLabel");
			String filterORing = filter.getString("pyFilterORing");
			String filterNameforLogic = filterName.replace("(", "");
			filterNameforLogic = filterNameforLogic.replace(")", "");
			filterNameforLogic = filterNameforLogic.replaceAll("\\s", "");

			String dataType =  filter.getString("pyDataType");
			String searchText = filter.getString("pySearchText");

			if(dataType.equals("Text") && !searchText.equals("")){

				doOring = true;
				String newFilterLabel = filterNameforLogic +i+"T";
				if (!StringUtils.isBlank(pyFilterLogicLabelPrefix)) {
					newFilterLabel = pyFilterLogicLabelPrefix + newFilterLabel;
				}

				ClipboardPage pgFilterNew = cpTempFilteR.getPageValue(ClipboardProperty.LIST_APPEND);

				pgFilterNew.putString("pyFilterName", filterName);
				pgFilterNew.putString("pyFilterOperation", "contains");
				pgFilterNew.putString("pyFilterValue", searchText);
				pgFilterNew.putString("pyLogicLabel", newFilterLabel);
				pgFilterNew.putString("pyCaseInsensitive", "true");
				if (useNullIfEmpty.equalsIgnoreCase("true")) {
					pgFilterNew.putString("pyUseNullIfEmpty", "true");
				} else {
					pgFilterNew.putString("pyUseNullIfEmpty", "false");
				}
				pyFilterLogic += ( newFilterLabel);
			}else if("Decimal".equals(dataType) || "Double".equals(dataType) || "Integer".equals(dataType) || "Date".equals(dataType)|| "DateTime".equals(dataType)) {

				boolean startFilter = false;
				boolean endFilter = false;

				String startRange = filter.getString("pyStart"+dataType);
				String endRange = filter.getString("pyEnd"+dataType);

				String newFilterLabel1 = filterNameforLogic;
				String newFilterLabel2 = filterNameforLogic;
				if(!startRange.equals("")){
					doOring = true;	
					startFilter = true;				
					if (!StringUtils.isBlank(pyFilterLogicLabelPrefix)) {
						newFilterLabel1 = pyFilterLogicLabelPrefix + newFilterLabel1+i+"sr";
					}
					ClipboardPage pgFilterNew = cpTempFilteR.getPageValue(ClipboardProperty.LIST_APPEND);

					pgFilterNew.putString("pyFilterName", filterName);

					pgFilterNew.putString("pyFilterOperation", ">=");

					pgFilterNew.putString("pyFilterValue", startRange);

					pgFilterNew.putString("pyLogicLabel", newFilterLabel1);


					if (useNullIfEmpty.equalsIgnoreCase("true")) {
						pgFilterNew.putString("pyUseNullIfEmpty", "true");
					} else {
						pgFilterNew.putString("pyUseNullIfEmpty", "false");
					}
				}
				if(!endRange.equals("")){
					endFilter = true;
					doOring = true;	
					if (!StringUtils.isBlank(pyFilterLogicLabelPrefix)) {
						newFilterLabel2 = pyFilterLogicLabelPrefix + newFilterLabel2+i+"er";
					}

					ClipboardPage pgFilterNew = cpTempFilteR.getPageValue(ClipboardProperty.LIST_APPEND);

					pgFilterNew.putString("pyFilterName", filterName);

					pgFilterNew.putString("pyFilterOperation",  "<=");

					pgFilterNew.putString("pyFilterValue", endRange);

					pgFilterNew.putString("pyLogicLabel", newFilterLabel2);


					if (useNullIfEmpty.equalsIgnoreCase("true")) {
						pgFilterNew.putString("pyUseNullIfEmpty", "true");
					} else {
						pgFilterNew.putString("pyUseNullIfEmpty", "false");
					}
				}
				if(startFilter && endFilter){
					pyFilterLogic += "(" +( newFilterLabel1) +" AND "+ newFilterLabel2 +")";
				}else if(startFilter){
					pyFilterLogic +=  newFilterLabel1;
				}else if(endFilter){
					pyFilterLogic += newFilterLabel2;
				}

				if("Date".equals(dataType)|| "DateTime".equals(dataType)){
					String displayTimePeriod = filter.getString("pyDisplayTimePeriod");

					if(!displayTimePeriod.equals("")) {
						doOring = true;
						String newFilterLabel = filterNameforLogic +i+"dsp";
						if (!StringUtils.isBlank(pyFilterLogicLabelPrefix)) {
							newFilterLabel = pyFilterLogicLabelPrefix + newFilterLabel;
						}

						ClipboardPage pgFilterNew = cpTempFilteR.getPageValue(ClipboardProperty.LIST_APPEND);

						pgFilterNew.putString("pyFilterName", filterName);
						pgFilterNew.putString("pyFilterOperation", "=");
						pgFilterNew.putString("pyFilterValue", displayTimePeriod);
						pgFilterNew.putString("pyLogicLabel", newFilterLabel);

						if (useNullIfEmpty.equalsIgnoreCase("true")) {
							pgFilterNew.putString("pyUseNullIfEmpty", "true");
						} else {
							pgFilterNew.putString("pyUseNullIfEmpty", "false");
						}
						if(startFilter || endFilter){
							pyFilterLogic += " OR " +( newFilterLabel);
						}
						else
							pyFilterLogic += ( newFilterLabel);
					}
				}
			}

			if (cpValueList != null) {

				for (int cnt = 1; cnt <= cpValueList.size(); cnt++) {
					ClipboardPage pgFilterNew = cpTempFilteR.getPageValue(ClipboardProperty.LIST_APPEND);

					String newFilterLabel = filterNameforLogic + cnt + i;
					if (!StringUtils.isBlank(pyFilterLogicLabelPrefix)) {
						newFilterLabel = pyFilterLogicLabelPrefix + newFilterLabel;
					}
					pgFilterNew.putString("pyFilterName", filterName);
					pgFilterNew.putString("pyFilterOperation", "=");
					pgFilterNew.putString("pyFilterValue", cpValueList.getStringValue(cnt));
					pgFilterNew.putString("pyLogicLabel", newFilterLabel);

					if (useNullIfEmpty.equalsIgnoreCase("true")) {
						pgFilterNew.putString("pyUseNullIfEmpty", "true");
					} else {
						pgFilterNew.putString("pyUseNullIfEmpty", "false");
					}
					if (cnt == 1 && !doOring) {
						pyFilterLogic += (newFilterLabel);
					} else {
						pyFilterLogic += (" OR " + newFilterLabel);
					}
				}
			}

			pyFilterLogic += (")");


			if (filterLogicfromAPI.indexOf(oldFilterLabel + " AND") > -1) {
				filterLogicfromAPI = filterLogicfromAPI.replaceAll(oldFilterLabel + " AND", pyFilterLogic + " AND ");
			}
			if (filterLogicfromAPI.indexOf(oldFilterLabel + " OR") > -1) {
				filterLogicfromAPI = filterLogicfromAPI.replaceAll(oldFilterLabel + " OR", pyFilterLogic + " OR ");
			}
			if (filterLogicfromAPI.indexOf(oldFilterLabel + " )") > -1) {
				filterLogicfromAPI = filterLogicfromAPI.replace(oldFilterLabel + " )", pyFilterLogic + " )");
			}
			if (filterLogicfromAPI.endsWith(oldFilterLabel)) {
				filterLogicfromAPI = filterLogicfromAPI.substring(0, filterLogicfromAPI.lastIndexOf(oldFilterLabel)) + pyFilterLogic;
			}
			//if FilterLogic is not set in embed-ReportFilters all the filter operations are ANDed
			if (i < cpFilter.size() && isFilterLogicBlank) {
				if( pyChangeFilterLogic.equals("true")){
					filterLogicfromRule += pyFilterLogic + " OR ";		
				}else
					if(filterORing.equals("true")){
						filterLogicfromRule += pyFilterLogic + " OR ";
					}
					else
						filterLogicfromRule += pyFilterLogic + " AND ";
			} else if (isFilterLogicBlank) {
				filterLogicfromRule += pyFilterLogic;
			}
		}
		if (!isFilterLogicBlank) {
			filterLogicfromRule += filterLogicfromAPI;
		}
		pgTempFilters.putString("pyFilterLogic", filterLogicfromRule);
	}
}

